import { readFile, mkdir, writeFile } from "node:fs/promises";
import type { Abi, Hex } from "viem";
import { format } from "prettier";

interface Artifact {
  abi: Abi;
  bytecode: { object: Hex };
}
await mkdir("packages/shared", { recursive: true });
let source =
  "// Generated by npm run abi from Foundry artifacts. Do not edit.\n";
for (const name of ["Confiance", "DemoToken"]) {
  const artifact = JSON.parse(
    await readFile(`contracts/out/${name}.sol/${name}.json`, "utf8"),
  ) as Artifact;
  if (
    !Array.isArray(artifact.abi) ||
    !/^0x[0-9a-f]+$/i.test(artifact.bytecode.object)
  ) {
    throw new Error(`Invalid artifact: ${name}`);
  }
  const prefix = name === "Confiance" ? "confiance" : "demoToken";
  source += `export const ${prefix}Abi = ${JSON.stringify(artifact.abi, null, 2)} as const;\n`;
  source += `export const ${prefix}Bytecode = '${artifact.bytecode.object}' as const;\n`;
}
await writeFile(
  "packages/shared/contracts.ts",
  await format(source, { parser: "typescript" }),
);
console.log("Generated typed ABI and deployment bytecode.");
